/**
 * The four series portrait panels, base64-inlined.
 *
 * The cards run on the edge runtime, so there is no fs, and fetching from
 * the site at build time would be circular.
 *
 * 460x630, not the brand kit's 580. Satori renders a 580-wide panel at
 * 479 and centres it, leaving a black strip down the right edge of every
 * card — the same layout with a 400 or 460 wide panel is flush. It is the
 * image width, not the layout: absolute, flex, img, background-image and
 * every combination of explicit sizing produced the same 479.
 *
 * The three the kit specifies as mono are greyscaled here rather than in
 * CSS: Satori has no filter support, so a grayscale() would have silently
 * done nothing and shipped four colour cards.
 */

export const seriesPhoto = {
  standing: 'data:image/jpeg;base64,',
  aob: 'data:image/jpeg;base64,',
  mec: 'data:image/jpeg;base64,',
  board: 'data:image/jpeg;base64,',
};
